/**
 * Reads the per-section llms indexes generated by `gen:llms`
 * (packages/docs-tooling/generated/llms-sections/<section>.txt). Build-time
 * only: the route that uses this is force-static.
 */
import fs from "node:fs";
import path from "node:path";
import { findRepoRoot } from "./repo-root";

export const LLMS_SECTIONS_REL =
  "packages/docs-tooling/generated/llms-sections";
const SECTION_PATTERN = /^[a-z0-9][a-z0-9-]*$/;

export function llmsSectionsDir(root = findRepoRoot()) {
  return root ? path.join(root, LLMS_SECTIONS_REL) : null;
}

export function listLlmsSections(dir = llmsSectionsDir()): string[] {
  if (!dir || !fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir)
    .filter((file) => file.endsWith(".txt"))
    .map((file) => file.slice(0, -".txt".length))
    .filter((section) => SECTION_PATTERN.test(section))
    .sort();
}

export function readLlmsSection(
  section: string,
  dir = llmsSectionsDir(),
): string | null {
  if (!dir || !SECTION_PATTERN.test(section)) return null;
  const file = path.join(dir, `${section}.txt`);
  return fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null;
}
